components.css:
.ds-device { display: flex; width: 100%; height: 152px; align-items: center; gap: 16px; padding: 16px; color: #f3f2f6; background: #222328; border: 1px solid #3d3e48; border-radius: 12px; text-align: left; font-family: system-ui; overflow: hidden; }
.ds-device-photo { display: grid; width: 112px; height: 104px; flex: none; place-items: center; color: #b8b8c5; background: #2c2d34; border-radius: 8px; }
.ds-device-photo svg { width: 46px; height: 46px; }
.ds-device-copy { display: grid; flex: 1; min-width: 0; gap: 4px; }
.ds-device-title { display: flex; justify-content: space-between; align-items: center; gap: 8px; font-size: 18px; font-weight: 670; line-height: 1.2; letter-spacing: -0.35px; }
.ds-device-title svg { color: #b8b8c5; }
.ds-device-state { display: flex; align-items: center; gap: 8px; min-height: 24px; color: #b8b8c5; font-size: 13px; font-weight: 500; }
.ds-device-state::before { content: ''; flex: none; width: 6px; height: 6px; border-radius: 3px; background: currentColor; }
.ds-device:hover { border-color: #b3b5ff; }
.ds-device:active { background: #373841; }
.ds-device:focus-visible { outline: 2px solid #c0c2ff; outline-offset: 2px; }

.ds-tabs { display: flex; gap: 4px; background: #222328; border-bottom: 1px solid #3d3e48; }
.ds-tabs button { display: inline-flex; align-items: center; justify-content: center; gap: 8px; width: 92px; height: 48px; padding: 0; border: 0; border-bottom: 2px solid transparent; border-radius: 0; background: transparent; color: #b8b8c5; font: 550 13px system-ui; }
.ds-tabs button:first-child { width: 112px; }
.ds-tabs button[aria-selected='true'] { color: #f3f2f6; border-bottom-color: #b3b5ff; font-weight: 650; }
.ds-tabs button[aria-selected='true'] svg { color: #b3b5ff; }
.ds-tabs button:hover { background: #373841; }
.ds-tabs button:active { background: #505481; }
.ds-tabs button:focus-visible { outline: 2px solid #c0c2ff; outline-offset: 2px; }

.ds-battery { display: grid; gap: 8px; padding: 16px; background: #222328; font-family: system-ui; }
.ds-battery-row { display: flex; justify-content: space-between; align-items: center; min-height: 24px; gap: 8px; }
.ds-battery-label { display: flex; align-items: center; gap: 8px; color: #b8b8c5; font-size: 13px; font-weight: 530; }
.ds-battery-reading { color: #f3f2f6; font-size: 14px; font-weight: 620; font-variant-numeric: tabular-nums; }
.ds-battery-track { height: 4px; background: #373841; border-radius: 2px; }
.ds-battery-track span { display: block; width: 37%; height: 100%; background: #b3b5ff; border-radius: 2px; }

.ds-apply { width: 112px; height: 40px; padding: 0 14px; border: 0; border-radius: 8px; color: #1a1b33; background: #b3b5ff; font: 500 14px/1.5 system-ui; }
.ds-apply:hover { background: #c7c8ff; }
.ds-apply:active { background: #a0a4fa; }
.ds-apply:focus-visible { outline: 2px solid #c0c2ff; outline-offset: 2px; }

.ds-preview { display: inline-flex; justify-content: center; align-items: center; gap: 8px; width: 80px; height: 38px; padding: 0; border: 1px solid #3d3e48; border-radius: 8px; background: #2c2d34; color: #f3f2f6; font: 500 14px/1.5 system-ui; }
.ds-preview:hover { background: #373841; }
.ds-preview:active { background: #505481; }
.ds-preview:focus-visible { outline: 2px solid #c0c2ff; outline-offset: 2px; }

.ds-dpi-label { display: inline-flex; gap: 8px; align-items: center; color: #b8b8c5; font: 600 12px system-ui; }
.ds-dpi { box-sizing: border-box; width: 80px; height: 40px; padding: 0 12px; border: 1px solid #3d3e48; border-radius: 8px; color: #f3f2f6; background: #2c2d34; font: 14px/1.5 system-ui; font-variant-numeric: tabular-nums; }
.ds-dpi[aria-invalid='true'] { border-color: #ffabaf; }
.ds-dpi::selection { background: #4b4d83; }
.ds-dpi:focus-visible { outline: 2px solid #c0c2ff; outline-offset: 2px; }

.ds-polling { display: flex; gap: 4px; padding: 4px; background: #373841; border-radius: 8px; }
.ds-polling button { flex: 1; min-width: 0; height: 32px; padding: 0; border: 0; border-radius: 4px; background: transparent; color: #f3f2f6; font: 500 14px/1.5 system-ui; font-variant-numeric: tabular-nums; }
.ds-polling button[aria-checked='true'] { background: #383b61; color: #e3e4ff; }
.ds-polling button:hover { background: #373841; }
.ds-polling button[aria-checked='true']:hover { background: #464a73; }
.ds-polling button:active, .ds-polling button[aria-checked='true']:active { background: #505481; }
.ds-polling button:focus-visible { outline: 2px solid #c0c2ff; outline-offset: 2px; }
